#include <iostream>
#include <fstream>
#include <vector>
#include <nlohmann/json.hpp>

using json = nlohmann::json;

int main() {
    json circleData;
    json polylineData;

    // Load circle annotations
    {
        std::ifstream in("circle_annotations.json");
        if (!in) { std::cerr << "Missing circle_annotations.json\n"; return 1; }
        in >> circleData;
    }

    // Load polyline annotations
    {
        std::ifstream in("polyline_annotations.json");
        if (!in) { std::cerr << "Missing polyline_annotations.json\n"; return 1; }
        in >> polylineData;
    }

    std::cout << "Loaded " << circleData.size() << " circles and "
              << polylineData.size() << " polylines.\n";
    return 0;
}
